"""Supplier-scoped original invoices and separately selected purchase references."""
HTML='''<section class="card" id="supplier-purchase-history" hidden><h2 id="supplier-history-title"></h2><p id="supplier-history-company"></p><p id="supplier-history-summary"></p><h3>FACTURAS ORIGINALES</h3><div class="scroll"><table><thead><tr><th>Factura / fecha</th><th>Neto</th><th>IVA</th><th>Total</th><th>Moneda</th><th>Fuente</th><th>Artículos</th></tr></thead><tbody id="supplier-history-invoices"></tbody></table></div><p id="supplier-history-no-invoices" hidden>Sin facturas originales consultables de este proveedor en la versión seleccionada.</p><h3>LÍNEAS RECIBIDAS SELECCIONADAS</h3><p id="supplier-history-status" role="status"></p><p>Se consultan aparte de las facturas originales. No se suman como facturas completas ni acreditan recepción, pago o existencias. Comparar el último coste sigue exigiendo proveedor de la ficha, SKU, unidad y EUR compatibles.</p><label>Buscar factura, SKU o archivo<input id="supplier-history-query" type="search"></label><p id="supplier-history-count" role="status"></p><div id="supplier-history-lines" class="scroll"></div><p id="supplier-history-empty" hidden></p><div class="files-actions"><button id="supplier-history-files" type="button">Revisar archivos recibidos</button><button id="supplier-history-prev" type="button">Anterior</button><button id="supplier-history-next" type="button">Siguiente</button></div></section>'''
JS=r'''
let supplierHistoryId=null,supplierHistoryPage=0;
function selectedSupplierPurchaseLines(){return state?.info?.dataset_id===$('dataset').value&&state.selected_purchase_history?.status==='SELECTED'?(state.received_purchase_lines||[]):[]}
function supplierReceivedPurchases(id){return selectedSupplierPurchaseLines().filter(line=>line.supplier_id===id)}
function resetSupplierPurchaseHistory(){supplierHistoryId=null;supplierHistoryPage=0;$('supplier-purchase-history').hidden=true;$('supplier-history-query').value='';['supplier-history-title','supplier-history-company','supplier-history-summary','supplier-history-status','supplier-history-count'].forEach(id=>$(id).textContent='');$('supplier-history-lines').replaceChildren();$('supplier-history-invoices').replaceChildren();$('supplier-history-empty').hidden=true;$('supplier-history-no-invoices').hidden=true;$('supplier-history-prev').disabled=true;$('supplier-history-next').disabled=true}
function supplierPortfolio(){
 const received=new Map(),invoices=new Map(),articles=new Map();selectedSupplierPurchaseLines().forEach(line=>received.set(line.supplier_id,(received.get(line.supplier_id)||0)+1));(state.purchase_documents?.invoices||[]).forEach(invoice=>invoices.set(invoice.supplier_id,(invoices.get(invoice.supplier_id)||0)+1));(state.articles||[]).forEach(article=>articles.set(article.supplier_id,(articles.get(article.supplier_id)||0)+1));$('supplier-purchase-scope').textContent=state.info.dataset_id===$('dataset').value?'Corte '+stockDate(state.info.as_of_date)+' · Facturas originales y líneas recibidas con recuentos separados. '+(state.selected_purchase_history?.message||'Los archivos de compras necesitan selección expresa para usarse como referencias comerciales.'):'Actualizando el historial de la empresa seleccionada…';$('suppliers-table').replaceChildren();
 (state.suppliers||[]).forEach(s=>{const row=document.createElement('tr');salesCells(row,[s.supplier_id,s.legal_name,s.contact_name||s.contact_person||'Sin configurar',s.delivery_location||s.delivery_address||'Sin configurar',articles.get(s.supplier_id)||0,invoices.get(s.supplier_id)||0,received.get(s.supplier_id)||0]);const td=document.createElement('td'),button=document.createElement('button');button.type='button';button.className='review-button';button.textContent='Ver compras';button.setAttribute('aria-label','Ver compras de '+(s.legal_name||s.supplier_id));button.onclick=()=>showSupplierPurchases(s.supplier_id);td.append(button);row.append(td);$('suppliers-table').append(row)});
}
function showSupplierPurchases(id){
 resetSupplierPurchaseHistory();if(state?.info?.dataset_id!==$('dataset').value)return;const supplier=(state.suppliers||[]).find(s=>s.supplier_id===id);if(!supplier)return;supplierHistoryId=id;const invoices=(state.purchase_documents?.invoices||[]).filter(invoice=>invoice.supplier_id===id);$('supplier-history-title').textContent='COMPRAS DE '+(supplier.legal_name||supplier.supplier_id)+' / '+supplier.supplier_id;$('supplier-history-company').textContent=state.info.company.legal_name+' · corte '+stockDate(state.info.as_of_date);$('supplier-history-summary').textContent=stockNumber(invoices.length)+' facturas originales · '+stockNumber(supplierReceivedPurchases(id).length)+' líneas recibidas seleccionadas.';$('supplier-history-status').textContent=state.selected_purchase_history?.message||'Sin historial recibido seleccionado. Recibe y selecciona sus archivos desde Carga de archivos para consultar esas referencias.';
 invoices.forEach(invoice=>{const row=document.createElement('tr');salesCells(row,[invoice.invoice_number+' · '+stockDate(invoice.issue_date),money(invoice.net_amount),money(invoice.vat_amount),money(invoice.gross_amount),invoice.currency,salesSource(invoice.source_refs)]);const td=document.createElement('td'),button=document.createElement('button');button.type='button';button.className='review-button';button.textContent='Ver artículos';button.onclick=()=>{view('compras');$('purchase-doc-search').value='';$('purchase-doc-supplier').value=id;filterPurchaseDocuments();showPurchaseDocument(invoice)};td.append(button);row.append(td);$('supplier-history-invoices').append(row)});$('supplier-history-no-invoices').hidden=invoices.length>0;filterSupplierReceivedHistory();$('supplier-purchase-history').hidden=false;$('supplier-purchase-history').scrollIntoView({behavior:'smooth',block:'start'});
}
function filterSupplierReceivedHistory(){
 if(!supplierHistoryId||state?.info?.dataset_id!==$('dataset').value){resetSupplierPurchaseHistory();return}const query=$('supplier-history-query').value.trim().toLocaleLowerCase('es'),all=supplierReceivedPurchases(supplierHistoryId),rows=all.filter(line=>!query||[line.invoice_number,line.article_id,...line.source_refs.map(ref=>ref.filename)].join(' ').toLocaleLowerCase('es').includes(query)).sort((a,b)=>b.issue_date.localeCompare(a.issue_date)||a.invoice_number.localeCompare(b.invoice_number)||a.article_id.localeCompare(b.article_id));supplierHistoryPage=Math.max(0,Math.min(supplierHistoryPage,Math.ceil(rows.length/100)-1));const page=rows.slice(supplierHistoryPage*100,(supplierHistoryPage+1)*100);purchaseReceivedTable('supplier-history-lines',page);$('supplier-history-count').textContent=stockNumber(all.length)+' líneas recibidas seleccionadas para este proveedor · '+stockNumber(rows.length)+' coincidencias · mostrando '+stockNumber(page.length)+' · página '+stockNumber(supplierHistoryPage+1)+' de '+stockNumber(Math.max(1,Math.ceil(rows.length/100)))+'. No son un recuento de facturas completas.';$('supplier-history-empty').hidden=page.length>0;$('supplier-history-empty').textContent=all.length?'No hay líneas que coincidan con esta búsqueda.':'Sin líneas recibidas seleccionadas para este proveedor. Consulta el estado del historial y las facturas originales.';$('supplier-history-prev').disabled=supplierHistoryPage===0;$('supplier-history-next').disabled=(supplierHistoryPage+1)*100>=rows.length;
}
$('supplier-history-query').addEventListener('input',()=>{supplierHistoryPage=0;filterSupplierReceivedHistory()});$('supplier-history-prev').onclick=()=>{supplierHistoryPage--;filterSupplierReceivedHistory()};$('supplier-history-next').onclick=()=>{supplierHistoryPage++;filterSupplierReceivedHistory()};$('supplier-history-files').onclick=()=>view('archivos');
'''
